using UnityEngine;
public sealed partial class TrainingFighter {
 TrainingMotionAction sampledMotion;float motionStart;
 public TrainingMotionAction MotionAction {get{var c=InputCharacter;if(c==null||StunRemaining>0||IsGuarding||IsDown||IsThrowState||IsAirCombatAttack)return null;if(IsAirDashing)return c.airDashAction;if(CurrentPhase==Phase.Air||CurrentPhase==Phase.Takeoff)return c.jumpAction;if(CurrentPhase==Phase.Backstep)return c.backstepAction;if(!IsGrounded)return null;if(IsCrouching)return CurrentPhase==Phase.Crouch?c.crouchAction:null;if(CurrentPhase==Phase.Idle)return c.idleAction;if(CurrentPhase==Phase.Move){if(HorizontalVelocity*Facing<-.01f)return c.backwardWalkAction;if(HasDashInertia||Mathf.Abs(HorizontalVelocity)>walkSpeed+.1f)return c.groundDashAction;return c.forwardWalkAction;}return null;}}
 public TrainingMotionPose MotionPose {get{var action=MotionAction;if(action!=sampledMotion||timer<motionStart){sampledMotion=action;motionStart=timer;}if(action==null||action.poses==null||action.poses.Length==0)return null;if(action.playback==TrainingMotionPlayback.JumpPhases&&action.poses.Length>=2)return action.poses[CurrentPhase==Phase.Takeoff||VerticalVelocity>0?0:1];if(action.playback==TrainingMotionPlayback.BackstepPhases&&action.poses.Length==9){var tuning=GetComponent<ApprovedLocomotionTuning>();float end1=tuning!=null?tuning.Applied.pose1EndFrame:definition.backstepSeconds*60/3,end2=tuning!=null?tuning.Applied.pose2EndFrame:2*definition.backstepSeconds*60/3;return action.poses[ArmoredStaticPoseView.BackstepSequenceIndex(definition.backstepSeconds-RemainingLockFrames/60f,end1,end2)];}return action.Sample(Mathf.Max(0,Mathf.FloorToInt((timer-motionStart)*60+.0001f)));}}
 public bool MotionHurtGeometry(int id,out Vector2 center,out Vector2 size){center=size=Vector2.zero;var pose=MotionPose;if(pose==null||pose.hurt==null)return false;foreach(var hurt in pose.hurt)if(hurt!=null&&hurt.partId==id){if(hurt.inheritBodyShape)return false;center=new Vector2(hurt.center.x*Facing,hurt.center.y);size=hurt.size;return true;}return false;}
}
